  "name": "Security approval for restricted data",
  "script": "(function executeRule(current, previous) {
    var restricted = ["client_master", "counterparty_exposure", "gl_actuals", "payroll"];
    if (restricted.indexOf(current.getValue('u_dataset')) < 0) return;
    var a = new GlideRecord('sysapproval_approver');
    a.initialize();
    a.sysapproval = current.sys_id;
    a.approver = '5bb1f05607167c49e249269b9e713986';  // security team lead
    a.state = 'requested';
    a.insert();
})(current, previous);"
 },
